package kr.workbench;
import burp.api.montoya.*;import burp.api.montoya.http.*;import burp.api.montoya.http.message.*;import burp.api.montoya.http.message.requests.*;import burp.api.montoya.internal.*;import javax.swing.*;import javax.swing.table.*;import java.util.*;import java.util.List;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class EnvironmentBatchTest extends WorkbenchTest {
 static void idle(EnvironmentPanel p)throws Exception{for(int i=0;i<1000;i++){edt(()->{});if(p.job==null)return;Thread.sleep(10);}throw new AssertionError("batch timeout");}
 static void fill(EnvironmentPanel p,String... urls){p.paths.setRowCount(0);p.candidates=Arrays.stream(urls).map(u->new EnvironmentCatalog.Candidate(u,"test","review",80,"")).toList();for(String u:urls)p.paths.addRow(new Object[]{u,"test","review","미검증"});}
 public static void main(String[] args)throws Exception{
 AtomicBoolean scope=new AtomicBoolean(true);AtomicInteger timeout=new AtomicInteger(),sent=new AtomicInteger();AtomicReference<RedirectionMode> redirect=new AtomicReference<>();AtomicReference<CountDownLatch> blocking=new AtomicReference<>();CountDownLatch entered=new CountDownLatch(1);
 ObjectFactoryLocator.FACTORY=proxy(MontoyaObjectFactory.class,(p,m,a)->switch(m.getName()){
 case "httpRequestFromUrl"->request((String)a[0],"GET",scope.get()&&!((String)a[0]).contains("outside"),List.of());
 case "requestOptions"->proxy(RequestOptions.class,(pp,mm,aa)->{if(mm.getName().equals("withResponseTimeout"))timeout.set(((Number)aa[0]).intValue());if(mm.getName().equals("withRedirectionMode"))redirect.set((RedirectionMode)aa[0]);return pp;});default->def(m);});
 var http=proxy(Http.class,(p,m,a)->{if(!m.getName().equals("sendRequest"))return def(m);HttpRequest q=(HttpRequest)a[0];check(!SwingUtilities.isEventDispatchThread(),"batch sends outside EDT");check(q.method().equals("GET")&&q.headers().isEmpty(),"batch uses anonymous GET");sent.incrementAndGet();if(blocking.get()!=null){entered.countDown();blocking.get().await(3,TimeUnit.SECONDS);}if(q.url().contains("error"))throw new IllegalStateException("fixture");var s=response(q.url().contains("denied")?403:200,"packet for "+q.url());return proxy(HttpRequestResponse.class,(pp,mm,aa)->switch(mm.getName()){case "request"->q;case "response"->s;default->def(mm);});});MontoyaApi api=proxy(MontoyaApi.class,(p,m,a)->m.getName().equals("http")?http:def(m));AtomicReference<EnvironmentPanel> box=new AtomicReference<>();edt(()->box.set(new EnvironmentPanel(api)));EnvironmentPanel panel=box.get();edt(()->panel.compareMissing.setSelected(false));
 edt(()->{fill(panel,"https://test/a","https://test/denied","https://test/error");panel.pathTable.setRowSelectionInterval(0,0);check(panel.requestView.getText().contains("GET /a")&&panel.responseView.getText().contains("미검증"),"selection previews unsent request without response");check(sent.get()==0,"selection sends no traffic");panel.start();panel.start();});idle(panel);check(sent.get()==3&&panel.packets.size()==3,"one batch visits every visible candidate exactly once");check(timeout.get()==10000&&redirect.get()==RedirectionMode.NEVER,"timeout and redirects disabled");
 edt(()->{((TableRowSorter<?>)panel.pathTable.getRowSorter()).setSortKeys(List.of(new RowSorter.SortKey(0,SortOrder.DESCENDING)));panel.pathTable.setRowSelectionInterval(0,0);check(panel.selectedUrl().endsWith("error")&&panel.responseView.getText().contains("요청 실패"),"sorted selection resolves corresponding error packet");panel.pathTable.setRowSelectionInterval(1,1);check(panel.responseView.getText().contains("403"),"selected response includes actual status packet");check(panel.start.isEnabled()&&!panel.stop.isEnabled(),"completion restores start and stop controls");fill(panel,"https://outside/a");panel.start();check(panel.job==null,"out of scope batch rejected before sending");});check(sent.get()==3,"rejected batch emits zero requests");
 blocking.set(new CountDownLatch(1));edt(()->{fill(panel,"https://test/first","https://test/second");panel.start();});check(entered.await(2,TimeUnit.SECONDS),"first request entered");edt(panel::stop);blocking.get().countDown();idle(panel);check(sent.get()==4,"stop prevents remaining requests");edt(()->{fill(panel,"https://test/one","https://test/only","https://test/three");panel.pathTable.setRowSelectionInterval(1,1);panel.startOne();});idle(panel);check(sent.get()==5&&panel.packets.containsKey("https://test/only")&&!panel.packets.containsKey("https://test/one"),"single start sends only selected candidate");edt(panel::close);check(panel.packets.isEmpty()&&panel.closed.get(),"unload clears packets and stops future work");System.out.println("EnvironmentBatchTest: "+checks+" checks passed");
 }
}
